/**
 * A top bar in four shapes. Axes: layout (inline: brand left, links, button right; split: the brand in the
 * middle with the links on both sides; search: a search field with its shortcut in the middle), over (none,
 * media: the bar sits over a picture, transparent), actions mode (none, cta), tone (default, inverse: on a dark
 * hero band). Turning solid on scroll is a port contract.
 */
import { type ReactNode } from "react";
import { Block, Box, Container, Grid, Group, LinkPlain } from "../compose";
import { MenuEntry } from "../components/menu-entry";
import { NavActions } from "../components/nav-actions";
import { NavBarMenu } from "../components/nav-bar-menu";
import { NavBlock } from "../components/nav-block";
import { NavLinks } from "../components/nav-links";
import { OverMedia } from "../components/over-media";
import { SearchPalette } from "../components/search-palette";
import { cn, tpl, uniqLabel } from "../utils";
import type { NavLink, NavBarActions, NavSearch } from "./nav-bar.types";

export type NavBarProps = {
  label: string;
  brand: string;
  brandHref?: string;
  links: NavLink[];
  current?: string;
  actions?: NavBarActions;
  search: NavSearch;
  tone?: "default" | "inverse";
  layout?: "inline" | "split" | "search";
  over?: "none" | "media";
  skip?: string;
  landmarkLabel?: string;
  onTheme?: () => void;
};

export function NavBar({
  label,
  brand,
  brandHref,
  links,
  current = "",
  actions,
  search,
  tone = "default",
  layout = "inline",
  over = "none",
  skip,
  landmarkLabel,
  onTheme,
}: NavBarProps) {
  return (
    <Block
      tag="header"
      className={cn(
        "relative",
        (
          (tone as string) === "inverse" ? "border-b border-transparent bg-foreground text-background [&_a]:text-background [&_button]:text-background"
          : "border-b border-border bg-background"
        ),
        (((over as string) === "media") ? "isolate overflow-hidden border-0 bg-transparent" : "")
      )}
      data-layout={layout}
      data-tone={tone}
      aria-label={landmarkLabel}
      data-slot="nav-bar"
    >
      <OverMedia on={((over as string) === "media")} alt={brand} />
      {skip ? (
        <LinkPlain
          href="#main-content"
          className={"sr-only focus:not-sr-only focus:fixed focus:left-2 focus:top-2 focus:z-50 focus:rounded focus:bg-background " +
            "focus:px-4 focus:py-2 focus:text-sm focus:inset-ring focus:inset-ring-border"}
          data-slot="skip-link"
        >
          {skip}
        </LinkPlain>
      ) : null}
      <Container className="mx-auto w-full max-w-6xl px-4" data-slot="container">
        <Box className={cn("flex flex-wrap items-center justify-between gap-4", "py-4")}>
          {((layout as string) === "split") ? (
            <NavBlock
              label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", label, landmarkLabel)) : label)}
              className="w-full"
              testid="site-nav"
            >
              <Grid cols="1-3" className="w-full items-center gap-4">
                <Box className="md:justify-self-start">
                  <NavLinks links={links} current={current} side="left" />
                </Box>
                <Box className="text-center">
                  <MenuEntry href={brandHref} className="text-lg font-medium" testid="brand">
                    {brand}
                  </MenuEntry>
                </Box>
                <Group gap="4" align="center" justify="end" className="flex-wrap md:justify-self-end">
                  <Box>
                    <NavLinks links={links} current={current} side="right" />
                  </Box>
                  <NavActions
                    login={actions?.login}
                    loginHref={actions?.loginHref}
                    cta={actions?.cta}
                    ctaHref={actions?.href}
                    actions={actions?.mode}
                    tone={tone}
                    themeLabel={actions?.themeLabel}
                    onTheme={() => onTheme?.()}
                  />
                </Group>
              </Grid>
            </NavBlock>
          ) : (
            <>
              <MenuEntry href={brandHref} className="text-lg font-medium" testid="brand">
                {brand}
              </MenuEntry>
              {((layout as string) === "search") ? (
                <SearchPalette label={search.label} shortcut={search.shortcut} />
              ) : null}
              <NavBarMenu label={label} links={links} current={current} landmarkLabel={landmarkLabel} />
              <NavActions
                login={actions?.login}
                loginHref={actions?.loginHref}
                cta={actions?.cta}
                ctaHref={actions?.href}
                actions={actions?.mode}
                tone={tone}
                themeLabel={actions?.themeLabel}
                onTheme={() => onTheme?.()}
              />
            </>
          )}
        </Box>
      </Container>
    </Block>
  );
}

