export type NavLink = {
  id: string;
  name: string;
  icon: string;
  href?: string;
};

export type NavBarActions = {
  /** cta: show the call to action */
  mode?: "none" | "cta";
  /** text of the call to action */
  cta?: string;
  /** href of the call to action */
  href?: string;
  /** text of the login link; none: no login */
  login?: string;
  /** href of the login link; none: a button with no address */
  loginHref?: string;
  /** text of the theme button; none: no button */
  themeLabel?: string;
};

export type NavSearch = {
  /** name and placeholder of the search field (layout search) */
  label: string;
  /** the keys that open the search, shown in the field */
  shortcut: string;
};
